<section class="panel form-panel"><h2>Tạo tài khoản</h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="user"><div class="form-grid"><label>Họ tên<input name="name" required maxlength="100" value="<?=e($_POST['name']??'')?>"></label><label>Email đăng nhập<input type="email" name="email" required maxlength="190" value="<?=e($_POST['email']??'')?>"></label><label>Mật khẩu ban đầu<input name="password" type="password" minlength="10" maxlength="255" required autocomplete="new-password"></label><label>Vai trò<select name="role"><?php foreach($roles as $r=>$label): ?><option value="<?=$r?>" <?=($_POST['role']??'dispatcher')===$r?'selected':''?>><?=$label?></option><?php endforeach ?></select></label><label class="span-2">Liên kết nhân viên (bắt buộc cho vai trò tài xế)<select name="driver_id"><option value="">Không liên kết</option><?php foreach(query('SELECT * FROM drivers WHERE active=1 ORDER BY name')->fetchAll() as $d): ?><option value="<?=$d['id']?>"><?=e($d['name'])?> · <?=e($d['phone'])?></option><?php endforeach ?></select></label></div><button class="btn primary">Tạo tài khoản</button></form></section>
